function dayStr(offset) {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() + offset);
  return d.toISOString().slice(0, 10);
}

function seeded(seed) {
  let s = seed;
  return () => {
    s = (s * 9301 + 49297) % 233280;
    return s / 233280;
  };
}

function buildHistory({ seed, days, prob, tailFlags, minMinutes, maxMinutes, binary }) {
  const rnd = seeded(seed);
  const flags = [];
  for (let i = 0; i < days - tailFlags.length; i++) {
    flags.push(rnd() < prob ? 1 : 0);
  }
  flags.push(...tailFlags);
  const history = {};
  flags.forEach((flag, idx) => {
    const offset = -(days - idx);
    if (flag) {
      history[dayStr(offset)] = binary
        ? 1
        : Math.round(minMinutes + rnd() * (maxMinutes - minMinutes));
    }
  });
  return history;
}

